"""Write notebook/analysis.ipynb from the cells below (keeps it in sync with src/).

Run `make notebook` to rebuild and execute it.
"""
from pathlib import Path

import nbformat as nbf

md, code = nbf.v4.new_markdown_cell, nbf.v4.new_code_cell

cells = [
    md("# Calder Ashby Engineering: spending and cash flow review, worked analysis\n\n"
       "> **Synthetic data - illustrative sample.** Calder Ashby Engineering is a fictional company. Every "
       "transaction, name and figure here is generated by `src/generate_data.py` (seed 42). No real company or "
       "client data is used.\n\n"
       "This notebook walks through the full pipeline: **clean → baseline → clusters → compare → charts**. "
       "All logic lives in `src/` and is imported here, so the notebook, the tests, the PNG/PDF charts and the web "
       "page all use the same code."),
    code("import sys, json\nfrom pathlib import Path\n\n"
         "ROOT = Path.cwd().resolve()\nif ROOT.name == 'notebook':\n    ROOT = ROOT.parent\n"
         "sys.path.insert(0, str(ROOT))\n\n"
         "import pandas as pd\nfrom IPython.display import Image, display\n\n"
         "from src import config, narrative as nv\n"
         "from src.clean import clean\n"
         "from src.analysis import DetectionConfig, daily_series, detect_clusters, weekly_net, cluster_table\n"
         "from src import charts_static\n\n"
         "pd.set_option('display.width', 160)\npd.set_option('display.max_colwidth', 90)"),
    md("## 1. The raw export\n\nThe raw file is deliberately messy: three date formats, amounts stored as text "
       "(`\"$1,234.50\"`, signed values), the same transaction exported twice, blank categories, and inconsistent "
       "casing and labels."),
    code("raw = pd.read_csv(config.RAW_CSV, dtype=str, keep_default_na=False)\nprint(f'{len(raw):,} raw rows')\n"
         "raw.sample(8, random_state=1)"),
    md("## 2. Cleaning, with a log of every fix"),
    code("tx, log = clean(raw)\nlog.to_frame()"),
    md("Because the data is synthetic, we can check the result against the generator's ground truth:"),
    code("truth = pd.read_csv(config.TRUTH_CSV, parse_dates=['date']).sort_values(['date', 'transaction_id'])"
         ".reset_index(drop=True)\n"
         "pd.testing.assert_frame_equal(tx, truth, check_dtype=False)\nprint('Cleaned data matches ground truth exactly.')"),
    md("## 3. Daily series and baseline\n\n"
       "Detection uses **operating spend**, which excludes scheduled payroll and rent because those are known in advance. "
       "Each day is adjusted for its weekday. The baseline is a rolling median of the previous 28 days, and the spread is "
       "MAD × 1.4826. Days inside a detected cluster are taken out of the baseline and it is recalculated."),
    code("cfg = DetectionConfig()\ncfg"),
    code("daily = daily_series(tx)\ndaily, clusters = detect_clusters(daily, cfg)\n"
         "daily[['outflow_operating', 'out_baseline', 'out_band_low', 'out_band_high', 'out_z', 'out_flagged']]"
         ".loc['2025-03-07':'2025-03-17'].round(2)"),
    md("## 4. Detected clusters vs planted anomalies"),
    code("planted = pd.DataFrame(json.loads(config.PLANTED_JSON.read_text()))[['id', 'kind', 'category', 'start', 'end']]\n"
         "detected = pd.DataFrame([{'kind': c.kind, 'start': c.start.date(), 'end': c.end.date(), 'days': c.n_days}"
         " for c in clusters])\n"
         "display(planted)\ndisplay(detected)"),
    md("## 5. How unusual is each cluster?\n\n"
       "Each cluster is compared with every other window of the same length that doesn't touch a cluster. "
       "The percentile is **descriptive** (the share of normal windows it beats), not a p-value. The 95% interval is a "
       "bootstrap of the cluster's own days."),
    code("cluster_table(clusters)"),
    md("### Sensitivity: what if the threshold were stricter or looser?"),
    code("rows = []\nfor z in (2.0, 2.5, 3.0, 3.5):\n    for run in (2, 3):\n"
         "        _, cl = detect_clusters(daily_series(tx), DetectionConfig(z_threshold=z, min_run=run))\n"
         "        rows.append({'z threshold': z, 'min run': run, 'clusters': len(cl),\n"
         "                     'periods': ', '.join(c.label for c in cl)})\npd.DataFrame(rows)"),
    md("### Robustness on data the method was not tuned on\n\n"
       "`src/robustness.py` regenerates the ledger with 30 other seeds (same planted anomalies, different noise) and "
       "scores the detector at default settings."),
    code("rob = json.loads((config.DATA_DIR / 'robustness.json').read_text())\n"
         "{k: v for k, v in rob.items() if k != 'rows'}"),
    md("## 6. Charts\n\nThe same functions write the 300 dpi PNG and vector PDF files in `outputs/`."),
    code("from src.analysis import Results\n"
         "r = Results(tx, log, daily, weekly_net(daily), clusters, cfg)\n"
         "paths = charts_static.build_all(r)\n"
         "for name, (png, pdf) in paths.items():\n"
         "    print(png.relative_to(config.ROOT), '|', pdf.relative_to(config.ROOT))"),
    code("display(Image(filename=str(paths['1_spending_velocity'][0]), width=900))\nprint(nv.velocity_insight(r))"),
    code("display(Image(filename=str(paths['2_cash_flow'][0]), width=900))\nprint(nv.cashflow_insight(r))"),
    code("display(Image(filename=str(paths['3_cluster_vs_normal'][0]), width=900))\nprint(nv.compare_insight(r))"),
    md("## 7. Limitations\n\n"
       "- The data is synthetic. Real ledgers have quirks this one lacks, such as quarter-ends, bank holidays and reversals.\n"
       "- The baseline needs about four weeks of history, so early January is not scored.\n"
       "- Short clusters give rough bootstrap intervals.\n"
       "- Windows overlap, so the reference periods aren't independent. This is another reason the percentiles "
       "are descriptive only.\n"
       "- A flag means *look here*, not *something is wrong*."),
]

nb = nbf.v4.new_notebook()
nb["cells"] = cells
nb["metadata"] = {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
                  "language_info": {"name": "python"}}
out = Path(__file__).with_name("analysis.ipynb")
nbf.write(nb, out)
print(out)
